insert into public.fms_items (hospital_id, kind, cat, cat_name, no, text, ref, red)
select null, v.* from (values
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1000, 'รายงานตรวจสอบระบบไฟฟ้าประจำปี ลงนามโดยวิศวกรระดับสามัญขึ้นไป และหลักฐานยื่นกรมสวัสดิการฯ ครบย้อนหลัง 3 ปี (รวม PM ไฟฟ้าใหญ่ประจำปี)', 'FMS.01.00 ME 1', true),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1001, 'รายงานตรวจสอบและรับรองระบบป้องกันอัคคีภัยประจำปี (ปั๊มดับเพลิง สปริงเกลอร์ ระบบแจ้งเหตุ) โดยผู้มีคุณสมบัติ', 'FMS.01.00 ME 1', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1002, 'รายงานระบบบำบัดน้ำเสีย ทส.1/ทส.2 ส่งครบทุกเดือน และผลตรวจน้ำทิ้งรายเดือนจากห้องปฏิบัติการที่ขึ้นทะเบียน (ต่อสัญญาผู้ตรวจเมื่อหมดอายุ)', 'FMS.01.00 ME 1', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1003, 'ผลตรวจวัดสภาพแวดล้อมในการทำงาน (แสง เสียง ความร้อน คุณภาพอากาศ IAQ/CO2) ตามรอบที่กฎหมายกำหนด และรายงานสรุปเสนอผู้บริหาร', 'FMS.01.00 ME 1', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1004, 'ผลตรวจระบบป้องกันฟ้าผ่าและค่าความต้านทานสายดินตามรอบ', 'FMS.01.00 ME 1', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1005, 'ตารางวันหมดอายุใบอนุญาต/ใบรับรองทุกฉบับ แจ้งเตือนล่วงหน้า 90 วัน และค้นเอกสารตัวจริงได้ภายใน 5 นาที', 'FMS.01.00 ME 1', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1006, 'ใบอนุญาตเก็บ/ใช้น้ำมันเชื้อเพลิง (ถังน้ำมัน Generator) และใบอนุญาตผู้ควบคุมเฉพาะทาง (ไฟฟ้า บำบัดน้ำเสีย พลังงาน) ไม่หมดอายุ', 'FMS.01.00 ME 1', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1007, 'แผนงบลงทุน (CapEx) จัดลำดับตามความเสี่ยงวิกฤต JCI พร้อมหลักฐานอนุมัติ และระยะเวลาออก PO งานวิศวกรรมเร่งด่วนตามเป้า (≤ 5 วันทำการ)', 'FMS.01.00 ME 3', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1008, 'ทะเบียนสัญญา MA ผู้รับเหมาภายนอกทุกระบบ (ลิฟต์ Chiller ดับเพลิง Fire alarm ประตูอัตโนมัติ คลีนรูม) ไม่หมดอายุ และไม่มีระบบสำคัญที่ไม่มีสัญญา', 'FMS.01.01 ME 2', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1009, 'ใบตรวจรับงานผู้รับเหมาทุกครั้งลงนามโดยผู้ควบคุมงาน และผลประเมินผู้รับเหมาตาม SLA/KPI อย่างน้อยปีละครั้ง (ระงับการจ่ายงวดเมื่อไม่ส่งรายงาน)', 'FMS.01.01 ME 2', false),
  ('doc', 'FMS01', 'FMS 01 ภาวะผู้นำและการวางแผน', 1010, 'บันทึกประชุมติดตามงานวิกฤต JCI รายสัปดาห์ (Master Action Plan: งาน ผู้รับผิดชอบ กำหนดเสร็จ งบ สถานะ)', 'FMS.01.01 ME 2', false),
  ('doc', 'FMS02', 'FMS 02 การประเมินความเสี่ยง', 1011, 'รายงานผลประเมินความเสี่ยงประจำปีเสนอผู้บริหารสูงสุด/Board พร้อมหลักฐานการรับทราบและสั่งการ', 'FMS.02.00 ME 1', false),
  ('doc', 'FMS02', 'FMS 02 การประเมินความเสี่ยง', 1012, 'ทะเบียนความเสี่ยงเครื่องจักร (FMEA/Asset risk) ระบุระดับความเสี่ยง ผลกระทบต่อพื้นที่วิกฤต และแผนลดความเสี่ยงรายเครื่อง', 'FMS.02.00 ME 2', false),
  ('doc', 'FMS03', 'FMS 03 ความปลอดภัย', 1013, 'ระบบรายงาน สอบสวน และวิเคราะห์อุบัติการณ์ด้านความปลอดภัยของอาคาร รวมเหตุความรุนแรงในที่ทำงาน (ME ใหม่ฉบับ 8)', 'FMS.03.00', false),
  ('doc', 'FMS03', 'FMS 03 ความปลอดภัย', 1014, 'Occurrence report ด้านระบบสาธารณูปโภคตอบกลับครบทุกเคส (สาเหตุ การแก้ไข การป้องกันซ้ำ CAPA) ภายในเวลาที่กำหนด', 'FMS.03.00', false),
  ('doc', 'FMS03', 'FMS 03 ความปลอดภัย', 1015, 'ขั้นตอนความปลอดภัยงานวิศวกรรม: LOTO งานไฟฟ้า/เครื่องจักร, ใบอนุญาตที่อับอากาศ (บ่อบำบัด ถังน้ำ) และบันทึกอุบัติเหตุ/Near miss ของช่าง', 'FMS.03.00', false),
  ('doc', 'FMS04', 'FMS 04 การรักษาความปลอดภัย', 1016, 'บันทึกการซ้อมเหตุด้าน Security (เด็กหาย Code Pink ผู้ก่อเหตุรุนแรง) และผลประเมิน', 'FMS.04.00', false),
  ('doc', 'FMS04', 'FMS 04 การรักษาความปลอดภัย', 1017, 'รายงานวิเคราะห์เหตุความรุนแรงในที่ทำงานประจำปี และการสอบสวนเหตุ Security พร้อมมาตรการป้องกันซ้ำ', 'FMS.04.00', false),
  ('doc', 'FMS04', 'FMS 04 การรักษาความปลอดภัย', 1018, 'หลักฐานการอบรม รปภ. (รวม Outsource) และทะเบียนสิทธิ์บัตรเข้าพื้นที่หวงห้ามที่เป็นปัจจุบัน', 'FMS.04.00', false),
  ('doc', 'FMS05', 'FMS 05 วัสดุอันตรายและของเสีย', 1019, 'Manifest การขนส่งของเสียอันตราย/ติดเชื้อ และใบอนุญาตผู้รับกำจัด รวมของเสียงานวิศวกรรม (น้ำมันใช้แล้ว หลอดไฟ แบตเตอรี่ กากตะกอน)', 'FMS.05.00 ME 5', false),
  ('doc', 'FMS06', 'FMS 06 อัคคีภัย', 1020, 'ผลทดสอบแรงดันน้ำดับเพลิงที่ชั้นบนสุด/ดาดฟ้า (≥ 65 PSI) และรายงานแก้ไขเมื่อไม่ถึง (คำนวณ Pump head / เปลี่ยนใบพัด)', 'FMS.06.00 ME 3', false),
  ('doc', 'FMS06', 'FMS 06 อัคคีภัย', 1021, 'รายงานจุด Fault / Disconnect ของระบบแจ้งเหตุเพลิงไหม้ = 0 หรือมีแผนแก้ไขพร้อมมาตรการชั่วคราวทุกจุด', 'FMS.06.02 ME 3', true),
  ('doc', 'FMS06', 'FMS 06 อัคคีภัย', 1022, 'แผนอพยพแนวราบ (Horizontal evacuation) สำหรับผู้ป่วยเคลื่อนย้ายยาก (ICU, OR, NICU, IVF) และลำดับการเคลื่อนย้ายอุปกรณ์สำคัญ', 'FMS.06.03', false),
  ('doc', 'FMS06', 'FMS 06 อัคคีภัย', 1023, 'ทะเบียนอุปกรณ์อพยพ (Evacuation sheet/chair) และบันทึกการฝึกใช้', 'FMS.06.03', false),
  ('doc', 'FMS06', 'FMS 06 อัคคีภัย', 1024, 'นโยบายห้ามสูบบุหรี่ในอาคาร/พื้นที่ รพ. ตามกฎหมาย และข้อยกเว้นสำหรับผู้ป่วย (ถ้ามี)', 'FMS.06.04', false),
  ('doc', 'FMS06', 'FMS 06 อัคคีภัย', 1025, 'บันทึกติดตามการปฏิบัติตามนโยบายห้ามสูบบุหรี่ และการดำเนินการเมื่อพบการฝ่าฝืน', 'FMS.06.04', false),
  ('doc', 'FMS07', 'FMS 07 เครื่องมือแพทย์', 1026, 'บันทึกตรวจรับก่อนใช้งาน (Incoming inspection) และทดสอบความปลอดภัยทางไฟฟ้า รวมเครื่องยืม/เช่า/บริจาค/ทดลองใช้จาก Supplier', 'FMS.07.00 ME 2', false),
  ('doc', 'FMS07', 'FMS 07 เครื่องมือแพทย์', 1027, 'นโยบายการใช้เครื่องจี้ไฟฟ้า (Electrosurgery) และตารางอบรมผู้ใช้งาน', 'FMS.07.00 ME 2', false),
  ('doc', 'FMS07', 'FMS 07 เครื่องมือแพทย์', 1028, 'รายงานอุบัติการณ์จากเครื่องมือแพทย์ การสอบสวน และการแจ้งผู้ผลิต/อย. เมื่อจำเป็น', 'FMS.07.01 ME 1', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1029, 'สถิติ Downtime ระบบวิกฤต (MTTR / MTBF) และ KPI ความพร้อมใช้ระบบสาธารณูปโภครายเดือน พร้อมการวิเคราะห์', 'FMS.08.00 ME 2', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1030, 'ผังการจ่ายไฟของ Generator แต่ละเครื่อง ไปยังพื้นที่ใด (โดยเฉพาะ ICU, OR, พื้นที่วิกฤต) เป็นปัจจุบัน', 'FMS.08.00 ME 3', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1031, 'ผล Thermoscan ตู้ MDB/แผงจ่ายไฟหลักอย่างน้อยปีละครั้ง และการแก้ไขจุดร้อน', 'FMS.08.00 ME 4', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1032, 'บันทึกการเดินระบบ (Log) เครื่องจักรสำคัญ Chiller / Cooling tower / Generator / บำบัดน้ำเสีย ครบทุกวัน ค่าสมเหตุสมผล', 'FMS.08.00 ME 4', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1033, 'การคำนวณปริมาณน้ำมันและน้ำสำรองเทียบชั่วโมงที่ รพ. กำหนด และรายการพื้นที่วิกฤตที่ต้องได้ไฟ/น้ำสำรอง', 'FMS.08.01 ME 1', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1034, 'ผลทดสอบ Generator มีโหลด ≥ 30% ทุกไตรมาส ย้อนหลัง 2–3 ปี และบันทึกเหตุไฟดับจริง (เวลา Gen รับโหลด ระยะเวลาเดิน ผลการทำงาน)', 'FMS.08.01 ME 3', true),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1035, 'บันทึกคลอรีนคงเหลือปลายก๊อกทุกชั้นและถังน้ำสำรองดาดฟ้า (รายวัน/รายเดือน) ร่วมกับ จป. และ Dashboard แสดงผล', 'FMS.08.02 ME 3', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1036, 'เกณฑ์ Alert / Action level ของน้ำ RO และขั้นตอนเมื่อผลเกินค่า', 'FMS.08.03 ME 2', false),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1037, 'รายงาน Validation / TAB ห้องผ่าตัดและคลีนรูม แยกรายห้อง (ACH ความดัน อนุภาค) จากผู้รับเหมา และใบรับรองครบทุกห้อง', 'FMS.08.04 ME 3', true),
  ('doc', 'FMS08', 'FMS 08 ระบบสาธารณูปโภค', 1038, 'ผลตรวจคุณภาพอากาศ CSSD / พื้นที่สะอาด ตามเกณฑ์ที่ถูกต้อง (รวมค่าฝุ่น) และการแก้ไขเมื่อไม่ผ่าน', 'FMS.08.04 ME 3', false),
  ('doc', 'FMS09', 'FMS 09 ภาวะฉุกเฉินและภัยพิบัติ', 1039, 'After-action report หลังซ้อม/เหตุจริง และหลักฐานการนำผลไปปรับแผน', 'FMS.09.00 ME 3', false),
  ('doc', 'FMS09', 'FMS 09 ภาวะฉุกเฉินและภัยพิบัติ', 1040, 'แผนรับเหตุฉุกเฉินระบบวิศวกรรมวิกฤต (ไฟดับ น้ำไม่ไหล แก๊สรั่ว ลิฟต์ค้าง น้ำท่วม) และคู่มือสลับแหล่งจ่าย (ATS / Bypass / Manual) ที่หน้างาน', 'FMS.09.00', false),
  ('doc', 'FMS09', 'FMS 09 ภาวะฉุกเฉินและภัยพิบัติ', 1041, 'แผนความต่อเนื่อง (BCP) ด้านอาคารและสาธารณูปโภค: บริการสำคัญ เป้าหมายเวลากู้คืน (RTO) อุปกรณ์สำรอง และ Reconstitution checklist', 'FMS.09.00', false),
  ('doc', 'FMS09', 'FMS 09 ภาวะฉุกเฉินและภัยพิบัติ', 1042, 'แผนสำรอง PPE/วัสดุจำเป็น และช่องทางประสานหน่วยงานสาธารณสุขภายนอกเมื่อเกิดโรคระบาด', 'FMS.09.01', false),
  ('doc', 'QAQS', 'QA/QS ระบบคุณภาพงานวิศวกรรม (สัญญา TOR)', 1043, 'งาน On-Hold ทุกใบระบุเหตุผลและกำหนดวันคาดว่าจะเสร็จ งานเกิน SLA มีการ Escalate', null, false),
  ('doc', 'QAQS', 'QA/QS ระบบคุณภาพงานวิศวกรรม (สัญญา TOR)', 1044, 'งานซ่อมที่ปิดแล้วมีรูปก่อน–หลังครบ และหัวหน้าตรวจรับก่อนปิดงานทุกใบ (สุ่ม 10 ใบ)', null, false),
