  ('tracer', 'TR8', 'TR8 สัญญา SLA และงานค้าง (ผู้ตรวจดูงาน Outsource)', 1114, 'งาน On-Hold ทุกใบมีเหตุผลและวันคาดว่าจะเสร็จ งานซ่อมปิดแล้วมีรูปก่อน-หลังและผู้ตรวจรับ (สุ่ม 10 ใบ)', 'FMS.01.01 ME 2', false),
  ('tracer', 'TR8', 'TR8 สัญญา SLA และงานค้าง (ผู้ตรวจดูงาน Outsource)', 1115, 'งานวิกฤต JCI ที่รอจัดซื้อ: ออก PO ภายในเป้า และมีผู้ติดตามรายสัปดาห์', 'FMS.01.01 ME 2', false),
  ('tracer', 'TR8', 'TR8 สัญญา SLA และงานค้าง (ผู้ตรวจดูงาน Outsource)', 1116, 'ผู้รับเหมาที่ไม่เข้าหน้างาน/ส่งรายงานไม่ครบ (เช่น Fire alarm, คลีนรูม, Chiller) มีหนังสือทวงและมาตรการตามสัญญา', 'FMS.01.01 ME 2', false)
) as v(kind, cat, cat_name, no, text, ref, red)
where not exists (select 1 from public.fms_items x where x.hospital_id is null and x.kind = v.kind and x.cat = v.cat and x.text = v.text);

-- keep the document and walk forms in ME order (new items sit after the existing items of the same ME); tracer forms keep their order
with o as (
  select id, row_number() over (partition by kind, cat order by
           (coalesce(ref, '') = ''),
           split_part(coalesce(ref, ''), ' ME ', 1),
           coalesce(nullif(split_part(coalesce(ref, ''), ' ME ', 2), '')::int, 99),
           no) as rn
  from public.fms_items where hospital_id is null and kind in ('doc', 'walk')
)
update public.fms_items i set no = o.rn from o where o.id = i.id and i.no <> o.rn;

with o as (select id, row_number() over (partition by kind, cat order by no) as rn from public.fms_items where hospital_id is null and kind = 'tracer')
update public.fms_items i set no = o.rn from o where o.id = i.id and i.no <> o.rn;
